expected = {1: (1000, 'USD'), 2: (2500, 'EUR'), 3: (700, 'USD'), 4: (1200, 'GBP')}
target = {1: (1000, 'USD'), 2: (2050, 'EUR'), 4: (1200, 'USD'), 5: (50, 'USD')}

def validate(expected, target):
    out = []
    if len(expected) != len(target):
        out.append(f'count: expected {len(expected)} got {len(target)}')
    se = sum(v[0] for v in expected.values())
    st = sum(v[0] for v in target.values())
    if se != st:
        out.append(f'sum: expected {se} got {st}')
    for k in sorted(set(expected) | set(target)):
        if k not in target:
            out.append(f'missing {k}')
        elif k not in expected:
            out.append(f'extra {k}')
        else:
            for i, name in enumerate(['amount_cents', 'currency']):
                if expected[k][i] != target[k][i]:
                    out.append(f'key {k} column {name}: expected {expected[k][i]} got {target[k][i]}')
    return out

for line in validate(expected, target):
    print(line)
print('problems', len(validate(expected, target)))

