WITH d AS (
  SELECT loaded_date, COUNT(*) AS n, SUM(amount_cents) AS total_cents, COUNT(DISTINCT currency) AS currencies
  FROM orders_clean
  GROUP BY loaded_date
)
SELECT loaded_date, n, total_cents, currencies,
       CASE WHEN n < 0.5 * AVG(n) OVER () THEN 'check' ELSE 'ok' END AS flag
FROM d
ORDER BY loaded_date;
